# Supprime de Studio les Pokemon d'id 1027 et plus (fichiers Data/Studio/pokemon) et psdk.dat (refait au lancement du jeu).
# Les Pokedex et les evolutions qui les citaient ont deja ete nettoyes. Les fichiers restent dans l'historique git.
$root = Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$dir = Join-Path $root 'Data\Studio\pokemon'
$names = @('adnokana.json', 'anenemy.json', 'atlasbel.json', 'basstile.json', 'beebrute.json', 'bellscrop.json', 'belstatue.json', 'browt.json', 'bunbon.json', 'buneaf.json', 'bunnolia.json', 'butterflare.json', 'cactussle.json', 'chariguana.json', 'chimelody.json', 'cirralop.json', 'clefaefae.json', 'combustang.json', 'cosmoink.json', 'cryscross.json', 'cubchestra.json', 'daurichu.json', 'deember.json', 'discupid.json', 'doechi.json', 'draphine.json', 'dronarch.json', 'ecosaur.json', 'eggvour.json', 'embertuff.json', 'felankh.json', 'ferrapin.json', 'floramona.json', 'forfowl_d.json', 'fortoise.json', 'fowln_tom.json', 'foxbell.json', 'froscowl.json', 'gecqua.json', 'geistuff.json', 'gengone.json', 'gigglyhuff.json', 'glacifern.json', 'glacifurr.json', 'glaciost.json', 'glanchog.json', 'gorochu.json', 'gryphlit.json', 'indicap.json', 'iron_moon.json', 'kangakid.json', 'kangallous.json', 'lediastra.json', 'lootbird.json', 'luloo.json', 'lumeon.json', 'lutramper.json', 'mewthree.json', 'miaoussieur.json', 'mimiegg.json', 'miraglacis.json', 'mirice.json', 'mr_fool.json', 'mr_jest.json', 'muschu.json', 'neutrun.json', 'nidominate.json', 'nidoregal.json', 'nohtyp.json', 'nuvoleon.json', 'nymbi.json', 'osselobber.json', 'pansimi.json', 'petalnia.json', 'pidgaero.json', 'pixiechu.json', 'platerigus.json', 'pombon.json', 'porygon_a.json', 'preciped.json', 'princie.json', 'psiloxie.json', 'pupglove.json', 'queendra.json', 'rampdily.json', 'ramptops.json', 'rattarule.json', 'rattchet.json', 'saberrime.json', 'sandslam.json', 'sectasite.json', 'selunabun.json', 'sepistrike.json', 'shorelorn.json', 'singesha.json', 'slowmate.json', 'sneerow.json', 'spiritales.json', 'sprousy.json', 'sunnydra.json', 'symbisaur.json', 'thunderpuff.json', 'thunphony.json', 'traumatisse.json', 'troutle.json', 'umamoth.json', 'ushu.json', 'velozolt.json', 'venacht.json', 'venomena.json', 'voltrinae.json', 'woadriate.json')
$n = 0
foreach ($f in $names) { $p = Join-Path $dir $f; if (Test-Path $p) { Remove-Item $p; $n++ } }
$dat = Join-Path $root 'Data\Studio\psdk.dat'; if (Test-Path $dat) { Remove-Item $dat }
Write-Host "$n Pokemon supprimes (psdk.dat sera refait au lancement du jeu)."
